// Setup route paths
function drawPaths() {
  for (const [pathId, seq] of Object.entries(sequences)) {
    const pathEl = document.getElementById(pathId);
    if (!pathEl) continue;
    let d = "";
    seq.forEach((id, idx) => {
      const pt = nodes[id];
      if (!pt) return;
      if (idx === 0) d += `M ${pt.x},${pt.y}`;
      else d += ` L ${pt.x},${pt.y}`;
    });
    pathEl.setAttribute("d", d);
  }
}

// 정거장 간 거리 드로잉
const distancesGroup = document.getElementById("distances-group");
function drawDistances() {
  if (!distancesGroup) return;
  distancesGroup.innerHTML = "";
  
  for (const [pair, distText] of Object.entries(segmentDistances)) {
    const [id1, id2] = pair.split("-");
    const pt1 = nodes[id1];
    const pt2 = nodes[id2];
    if (!pt1 || !pt2) continue;
    
    const cx = (pt1.x + pt2.x) / 2;
    const cy = (pt1.y + pt2.y) / 2;
    
    // 선분의 수직(법선) 방향으로 오프셋 계산 → 역 번호와 겹침 방지
    const dx = pt2.x - pt1.x;
    const dy = pt2.y - pt1.y;
    const len = Math.sqrt(dx * dx + dy * dy) || 1;
    const perpX = (-dy / len) * 10;  // 왼쪽으로 10px
    const perpY = (dx / len) * 10;
    const lx = cx + perpX;
    const ly = cy + perpY;
    
    const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
    g.setAttribute("class", "distance-label");
    g.setAttribute("style", "pointer-events: none;");
    
    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("x", lx);
    text.setAttribute("y", ly);
    text.setAttribute("fill", "#000000");
    text.setAttribute("font-family", "Inter, Noto Sans KR");
    text.setAttribute("font-size", "4.8px");
    text.setAttribute("font-weight", "800");
    text.setAttribute("text-anchor", "middle");
    text.setAttribute("dominant-baseline", "middle");
    text.textContent = distText;
    
    // rect sizing based on text length
    const rectW = distText.length * 2.8 + 3;
    const rectH = 6.5;
    
    const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    rect.setAttribute("x", lx - rectW / 2);
    rect.setAttribute("y", ly - rectH / 2);
    rect.setAttribute("width", rectW);
    rect.setAttribute("height", rectH);
    rect.setAttribute("fill", "#ffffff");
    rect.setAttribute("stroke", "#475569");
    rect.setAttribute("stroke-width", "0.5");
    rect.setAttribute("rx", "1");
    rect.setAttribute("ry", "1");
    
    g.appendChild(rect);
    g.appendChild(text);
    distancesGroup.appendChild(g);
  }
}

// 분기기 규격 드로잉
const turnoutsGroup = document.getElementById("turnouts-group");
function drawTurnouts() {
  if (!turnoutsGroup) return;
  turnoutsGroup.innerHTML = "";
  
  for (const [stnId, data] of Object.entries(turnoutData)) {
    const pt = nodes[stnId];
    if (!pt) continue;
    
    const tx = pt.x;
    const ty = pt.y + 11;
    
    const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
    g.setAttribute("class", "turnout-label");
    g.setAttribute("style", "pointer-events: none;");
    
    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("x", tx);
    text.setAttribute("y", ty);
    text.setAttribute("fill", "#ea580c");
    text.setAttribute("font-family", "Inter, Noto Sans KR");
    text.setAttribute("font-size", "4.2px");
    text.setAttribute("font-weight", "800");
    text.setAttribute("text-anchor", "middle");
    text.setAttribute("dominant-baseline", "middle");
    text.textContent = `⛙ ${data.spec}`;
    
    const textLen = `⛙ ${data.spec}`.length;
    const rectW = textLen * 2.3 + 3;
    const rectH = 5.5;
    
    const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    rect.setAttribute("x", tx - rectW / 2);
    rect.setAttribute("y", ty - rectH / 2);
    rect.setAttribute("width", rectW);
    rect.setAttribute("height", rectH);
    rect.setAttribute("fill", "rgba(254, 243, 199, 0.95)");
    rect.setAttribute("stroke", "#ea580c");
    rect.setAttribute("stroke-width", "0.4");
    rect.setAttribute("rx", "1");
    rect.setAttribute("ry", "1");
    
    g.appendChild(rect);
    g.appendChild(text);
    turnoutsGroup.appendChild(g);
  }
}

