// Zoom and Pan implementation
const svg = document.getElementById("map-svg");
const container = document.getElementById("map-container");
let scale = 1;
let pointX = 0;
let pointY = 0;
let startX = 0;
let startY = 0;
let isPanning = false;

function setTransform() {
  svg.style.transform = `translate(${pointX}px, ${pointY}px) scale(${scale})`;
  svg.style.transformOrigin = "0 0";
}

container.addEventListener("mousedown", (e) => {
  svg.style.transition = "none";
  if (e.target.classList.contains("station-marker")) return;
  isPanning = true;
  startX = e.clientX - pointX;
  startY = e.clientY - pointY;
});

container.addEventListener("mousemove", (e) => {
  if (!isPanning) return;
  pointX = e.clientX - startX;
  pointY = e.clientY - startY;
  setTransform();
});

window.addEventListener("mouseup", () => {
  isPanning = false;
});

container.addEventListener("wheel", (e) => {
  svg.style.transition = "none";
  e.preventDefault();
  const xs = (e.clientX - container.offsetLeft - pointX) / scale;
  const ys = (e.clientY - container.offsetTop - pointY) / scale;
  const delta = -e.deltaY;
  
  if (delta > 0) scale *= 1.1;
  else scale /= 1.1;
  
  scale = Math.min(Math.max(0.5, scale), 8);
  pointX = e.clientX - container.offsetLeft - xs * scale;
  pointY = e.clientY - container.offsetTop - ys * scale;
  
  setTransform();
});

// Button zoom controls
document.getElementById("zoom-in").addEventListener("click", () => {
  svg.style.transition = "transform 0.3s ease";
  scale = Math.min(scale * 1.3, 8);
  setTransform();
  setTimeout(() => { svg.style.transition = "none"; }, 300);
});
document.getElementById("zoom-out").addEventListener("click", () => {
  svg.style.transition = "transform 0.3s ease";
  scale = Math.max(scale / 1.3, 0.5);
  setTransform();
  setTimeout(() => { svg.style.transition = "none"; }, 300);
});
document.getElementById("zoom-reset").addEventListener("click", () => {
  svg.style.transition = "transform 0.3s ease";
  scale = 1;
  pointX = 0;
  pointY = 0;
  setTransform();
  setTimeout(() => { svg.style.transition = "none"; }, 300);
});

function focusCoordinates(x, y) {
  const containerW = container.clientWidth;
  const containerH = container.clientHeight;
  
  const svgRatio = 625 / 657;
  const containerRatio = containerW / containerH;
  
  let baseSvgWidth, baseSvgHeight;
  if (containerRatio > svgRatio) {
    baseSvgHeight = containerH;
    baseSvgWidth = containerH * svgRatio;
  } else {
    baseSvgWidth = containerW;
    baseSvgHeight = containerW / svgRatio;
  }
  
  const svgLeft = (containerW - baseSvgWidth) / 2;
  const svgTop = (containerH - baseSvgHeight) / 2;
  
  scale = 2.5; // Zoom in for details
  
  const screenX = svgLeft + (x / 625) * baseSvgWidth;
  const screenY = svgTop + (y / 657) * baseSvgHeight;
  
  pointX = containerW / 2 - screenX * scale;
  pointY = containerH / 2 - screenY * scale;
  
  svg.style.transition = "transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)";
  setTransform();
  setTimeout(() => {
    svg.style.transition = "none";
  }, 400);
}

// Quick navigation select
