// Font size sizing
function applyFontSize(size) {
  document.body.classList.remove("fs-small", "fs-medium", "fs-large");
  if (size === "small") {
    document.body.style.fontSize = "0.85rem";
    document.getElementById("btn-fs-small").style.background = "var(--border-color)";
    document.getElementById("btn-fs-medium").style.background = "";
    document.getElementById("btn-fs-large").style.background = "";
  } else if (size === "large") {
    document.body.style.fontSize = "1.15rem";
    document.getElementById("btn-fs-large").style.background = "var(--border-color)";
    document.getElementById("btn-fs-small").style.background = "";
    document.getElementById("btn-fs-medium").style.background = "";
  } else {
    document.body.style.fontSize = "1rem";
    document.getElementById("btn-fs-medium").style.background = "var(--border-color)";
    document.getElementById("btn-fs-small").style.background = "";
    document.getElementById("btn-fs-large").style.background = "";
  }
  localStorage.setItem("v1-font", size);
}
document.getElementById("btn-fs-small").addEventListener("click", () => applyFontSize("small"));
document.getElementById("btn-fs-medium").addEventListener("click", () => applyFontSize("medium"));
document.getElementById("btn-fs-large").addEventListener("click", () => applyFontSize("large"));

// --- Route path hover tooltip events ---
function bindRoutePathEvents() {
  const routePaths = document.querySelectorAll("#routes-group path");
  routePaths.forEach(p => {
    p.addEventListener("mouseenter", (e) => {
      const name = p.getAttribute("data-name") || "";
      if (name) showTooltipAt(e.offsetX, e.offsetY, name);
    });
    p.addEventListener("mouseleave", hideTooltip);
  });
}

window.addEventListener("DOMContentLoaded", () => {
  bindRoutePathEvents();
});

// --- 교차로 상세 확대 도면 팝업 모달 JS ---

// --- 교차로 상세 확대 도면 팝업 모달 JS (완벽 복원) ---
function openIntersectionModal(item) {
  if (!item) return;
  const modal = document.getElementById("intersection-zoom-modal");
  if (!modal) return;
  currentModalItem = item;
  switchModalViewMode("DIAGRAM");

  const is1 = item.tool === "1공구";
  const badgeEl = document.getElementById("modal-tool-badge");
  if (badgeEl) {
    badgeEl.textContent = `${item.tool || ''} #${item.no || ''}`;
    badgeEl.style.background = is1 ? "#ffedd5" : "#dbeafe";
    badgeEl.style.color = is1 ? "#c2410c" : "#1e40af";
  }

  const titleEl = document.getElementById("modal-title");
  if (titleEl) titleEl.textContent = `${item.name || '교차로'} 상세 확대 도면`;

  const staEl = document.getElementById("modal-sta-badge");
  if (staEl) staEl.textContent = `STA ${item.startSta || 0}m ~ ${item.endSta || 0}m (총 ${item.length || 0}m)`;

  // Generate SVG Diagram
  renderModalSvgDiagram(item);

  // Render Specs Grid
  const gridEl = document.getElementById("modal-specs-grid");
  if (gridEl) {
    gridEl.innerHTML = `
      <div class="spec-card">
        <div class="spec-card-title">교차로 구간 총 연장</div>
        <div class="spec-card-value" style="color: ${is1 ? '#ea580c' : '#2563eb'};">${item.length || 0} m</div>
      </div>
      <div class="spec-card">
        <div class="spec-card-title">체이닝 위치 (STA)</div>
        <div class="spec-card-value">${item.startSta || 0}m ~ ${item.endSta || 0}m</div>
      </div>
      <div class="spec-card">
        <div class="spec-card-title">적용 공법</div>
        <div class="spec-card-value">${item.method || '-'}</div>
      </div>
      <div class="spec-card">
        <div class="spec-card-title">교통처리 단계</div>
        <div class="spec-card-value">${item.stage || '-'} 단계</div>
      </div>
    `;
  }

  modal.classList.add("open");
  modal.classList.add("active");
  startTrafficSimulation(); // compatibility
}

function closeIntersectionModal() {
  const modal = document.getElementById("intersection-zoom-modal");
  if (modal) {
    modal.classList.remove("open");
    modal.classList.remove("active");
  stopTrafficSimulation();
  }
}

function closeIntersectionModalOnBackdrop(e) {
  if (e.target.id === "intersection-zoom-modal") {
    closeIntersectionModal();
  }
}

if (!window._modalEscListenerAdded) {
  window._modalEscListenerAdded = true;
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeIntersectionModal();
  });
}

